:root {
    --color-primary: #1a1a1a;
    --color-secondary: #6b7280;
    --color-accent: #dc2626;
    --color-accent-light: #fee2e2;
    --color-success: #10b981;
    --color-neutral-50: #f9fafb;
    --color-neutral-100: #f3f4f6;
    --color-neutral-200: #e5e7eb;
    --color-neutral-300: #d1d5db;
    --color-neutral-400: #9ca3af;
    --color-neutral-500: #6b7280;
    --color-neutral-600: #4b5563;
    --color-neutral-700: #374151;
    --color-neutral-800: #1f2937;
    --color-neutral-900: #111827;

    --spacing-xs: 0.25rem;
    --spacing-sm: 0.5rem;
    --spacing-md: 1rem;
    --spacing-lg: 1.5rem;
    --spacing-xl: 2rem;
    --spacing-2xl: 3rem;
    --spacing-3xl: 4rem;

    --radius-sm: 0.375rem;
    --radius-md: 0.5rem;
    --radius-lg: 0.75rem;
    --radius-xl: 1rem;

    --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1);
    --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.1);

    --transition-fast: 150ms ease-in-out;
    --transition-base: 250ms ease-in-out;
    --transition-slow: 350ms ease-in-out;

    --font-family-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;

    --container-max-width: 1200px;
    --container-padding: var(--spacing-xl);
}

/* Reset & Base */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-family-sans);
    color: var(--color-primary);
    background-color: #fff;
    line-height: 1.6;
}

/* Skip Link (Accessibility) */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background-color: var(--color-accent);
    color: white;
    padding: var(--spacing-md);
    text-decoration: none;
    z-index: 100;
}

.skip-link:focus {
    top: 0;
}

/* Container */
.container {
    max-width: var(--container-max-width);
    margin: 0 auto;
    padding: 0 var(--container-padding);
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
    line-height: 1.2;
    font-weight: 600;
    margin-bottom: var(--spacing-md);
}

h1 {
    font-size: clamp(2rem, 5vw, 3.5rem);
}

h2 {
    font-size: clamp(1.75rem, 4vw, 2.5rem);
}

h3 {
    font-size: 1.5rem;
}

p {
    margin-bottom: var(--spacing-md);
}

a {
    color: var(--color-primary);
    text-decoration: none;
    transition: color var(--transition-fast);
}

a:hover {
    color: var(--color-accent);
}

a:focus {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

/* Buttons */
.btn {
    display: inline-block;
    padding: var(--spacing-md) var(--spacing-lg);
    border: none;
    border-radius: var(--radius-lg);
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: all var(--transition-base);
    text-align: center;
    text-decoration: none;
}

.btn-primary {
    background-color: var(--color-accent);
    color: white;
}

.btn-primary:hover {
    background-color: #b91c1c;
    transform: translateY(-2px);
    box-shadow: var(--shadow-lg);
}

.btn-primary:focus {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

.btn-primary:active {
    transform: translateY(0);
}

.btn-secondary {
    background-color: var(--color-neutral-100);
    color: var(--color-primary);
    border: 1px solid var(--color-neutral-200);
}

.btn-secondary:hover {
    background-color: var(--color-neutral-200);
}

/* Icon Button */
.icon-button {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 2.5rem;
    height: 2.5rem;
    border: none;
    background: transparent;
    cursor: pointer;
    color: var(--color-primary);
    transition: color var(--transition-fast);
    border-radius: var(--radius-md);
}

.icon-button:hover {
    color: var(--color-accent);
}

.icon-button:focus {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

/* Header */
.header {
    background-color: white;
    border-bottom: 1px solid var(--color-neutral-100);
    position: sticky;
    top: 0;
    z-index: 50;
}

.header-top {
    padding: var(--spacing-lg) 0;
}

.header-nav {
    display: flex;
    align-items: center;
    gap: var(--spacing-3xl);
    flex: 1;
}

.logo {
    display: flex;
    align-items: center;
    gap: var(--spacing-md);
    font-weight: 700;
    font-size: 1.25rem;
    transition: color var(--transition-fast);
}

.logo:hover {
    color: var(--color-accent);
}

.logo-icon {
    color: var(--color-accent);
}

.logo-text {
    color: var(--color-primary);
}

.nav-links {
    display: flex;
    gap: var(--spacing-2xl);
}

.nav-link {
    font-size: 0.95rem;
    font-weight: 500;
    color: var(--color-primary);
    position: relative;
    padding-bottom: var(--spacing-xs);
}

.nav-link::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    width: 0;
    height: 2px;
    background-color: var(--color-accent);
    transition: width var(--transition-fast);
}

.nav-link:hover::after {
    width: 100%;
}

.header-top > .container {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-xl);
}

.header-actions {
    display: flex;
    align-items: center;
    gap: var(--spacing-md);
}

/* Hero Section */
.hero {
    position: relative;
    overflow: hidden;
    padding: var(--spacing-3xl) var(--spacing-container-padding);
    min-height: 500px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.hero-content {
    position: relative;
    z-index: 10;
    text-align: center;
    max-width: 600px;
}

.hero-title {
    font-size: clamp(2.5rem, 6vw, 4rem);
    margin-bottom: var(--spacing-lg);
    color: var(--color-primary);
}

.hero-subtitle {
    font-size: 1.25rem;
    color: var(--color-secondary);
    margin-bottom: var(--spacing-2xl);
    line-height: 1.6;
}

.hero-background {
    position: absolute;
    inset: 0;
    z-index: 0;
}

.gradient-circle {
    position: absolute;
    border-radius: 50%;
    opacity: 0.1;
}

.circle-1 {
    width: 400px;
    height: 400px;
    background: linear-gradient(135deg, var(--color-accent), var(--color-accent-light));
    top: -100px;
    right: -100px;
}

.circle-2 {
    width: 300px;
    height: 300px;
    background: linear-gradient(135deg, #60a5fa, #3b82f6);
    bottom: -50px;
    left: -50px;
}

/* Sections */
.section {
    padding: var(--spacing-3xl) 0;
}

.deals-section {
    padding: var(--spacing-3xl) 0;
    background-color: var(--color-neutral-50);
}

.editorial-section {
    padding: var(--spacing-3xl) 0;
    background-color: #f5f3ff;
}

.section-header {
    text-align: center;
    margin-bottom: var(--spacing-3xl);
}

.section-header h2 {
    color: var(--color-primary);
}

.section-subtitle {
    color: var(--color-secondary);
    font-size: 1.1rem;
    margin-bottom: 0;
}

/* Products Grid */
.products-grid,
.deals-grid,
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: var(--spacing-2xl);
}

/* Product Card */
.product-card {
    background: white;
    border-radius: var(--radius-lg);
    overflow: hidden;
    transition: all var(--transition-base);
    box-shadow: var(--shadow-sm);
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    box-shadow: var(--shadow-lg);
    transform: translateY(-4px);
}

.product-image {
    position: relative;
    width: 100%;
    aspect-ratio: 1;
    background: linear-gradient(135deg, var(--color-neutral-100), var(--color-neutral-200));
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.product-badge {
    position: absolute;
    top: var(--spacing-md);
    right: var(--spacing-md);
    background-color: var(--color-accent);
    color: white;
    padding: var(--spacing-xs) var(--spacing-md);
    border-radius: var(--radius-sm);
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    z-index: 10;
}

.product-info {
    padding: var(--spacing-lg);
    flex: 1;
    display: flex;
    flex-direction: column;
}

.product-category {
    font-size: 0.85rem;
    color: var(--color-secondary);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: var(--spacing-xs);
}

.product-name {
    font-size: 1.1rem;
    font-weight: 600;
    margin-bottom: var(--spacing-sm);
    color: var(--color-primary);
    line-height: 1.4;
}

.product-description {
    font-size: 0.9rem;
    color: var(--color-secondary);
    margin-bottom: auto;
    margin-bottom: var(--spacing-md);
}

.product-pricing {
    display: flex;
    align-items: baseline;
    gap: var(--spacing-md);
    margin-bottom: var(--spacing-lg);
}

.product-price {
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--color-primary);
}

.product-original-price {
    font-size: 0.95rem;
    color: var(--color-secondary);
    text-decoration: line-through;
}

.product-discount {
    font-size: 0.85rem;
    color: var(--color-success);
    font-weight: 600;
}

.product-rating {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
    margin-bottom: var(--spacing-lg);
    font-size: 0.9rem;
}

.stars {
    display: flex;
    gap: 2px;
}

.star {
    color: #fbbf24;
}

.product-actions {
    display: flex;
    gap: var(--spacing-md);
}

.product-btn {
    flex: 1;
    padding: var(--spacing-md);
    border: none;
    border-radius: var(--radius-md);
    font-weight: 600;
    cursor: pointer;
    transition: all var(--transition-fast);
}

.product-btn-add {
    background-color: var(--color-accent);
    color: white;
}

.product-btn-add:hover {
    background-color: #b91c1c;
}

.product-btn-favorite {
    background-color: var(--color-neutral-100);
    color: var(--color-primary);
    border: 1px solid var(--color-neutral-200);
}

.product-btn-favorite:hover {
    background-color: var(--color-accent-light);
    border-color: var(--color-accent);
    color: var(--color-accent);
}

/* Deal Card */
.deal-card {
    background: white;
    border-radius: var(--radius-lg);
    overflow: hidden;
    box-shadow: var(--shadow-sm);
    display: grid;
    grid-template-columns: 1fr 1fr;
    transition: all var(--transition-base);
}

.deal-card:hover {
    box-shadow: var(--shadow-lg);
}

.deal-image {
    background: linear-gradient(135deg, var(--color-neutral-100), var(--color-neutral-200));
    aspect-ratio: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}

.deal-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.deal-content {
    padding: var(--spacing-lg);
    display: flex;
    flex-direction: column;
    justify-content: center;
}

.deal-badge {
    display: inline-flex;
    background-color: var(--color-accent);
    color: white;
    padding: var(--spacing-sm) var(--spacing-md);
    border-radius: var(--radius-sm);
    font-weight: 700;
    font-size: 0.85rem;
    text-transform: uppercase;
    width: fit-content;
    margin-bottom: var(--spacing-md);
}

.deal-title {
    font-size: 1.25rem;
    font-weight: 700;
    margin-bottom: var(--spacing-sm);
}

.deal-description {
    color: var(--color-secondary);
    font-size: 0.95rem;
    margin-bottom: var(--spacing-lg);
}

.deal-timer {
    font-size: 0.85rem;
    color: var(--color-accent);
    font-weight: 600;
    margin-bottom: var(--spacing-md);
}

/* Editorial Card */
.editorial-card {
    background: white;
    border-radius: var(--radius-lg);
    overflow: hidden;
    box-shadow: var(--shadow-sm);
    transition: all var(--transition-base);
    display: flex;
    flex-direction: column;
}

.editorial-card:hover {
    box-shadow: var(--shadow-lg);
    transform: translateY(-4px);
}

.editorial-image {
    width: 100%;
    aspect-ratio: 16 / 10;
    background: linear-gradient(135deg, #e0e7ff, #f0f4ff);
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
}

.editorial-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.editorial-tag {
    display: inline-block;
    background-color: #e0e7ff;
    color: #4c1d95;
    padding: var(--spacing-xs) var(--spacing-md);
    border-radius: var(--radius-sm);
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    margin-bottom: var(--spacing-md);
}

.editorial-content-inner {
    padding: var(--spacing-lg);
    flex: 1;
    display: flex;
    flex-direction: column;
}

.editorial-title {
    font-size: 1.1rem;
    font-weight: 700;
    margin-bottom: var(--spacing-md);
    line-height: 1.4;
}

.editorial-excerpt {
    color: var(--color-secondary);
    font-size: 0.95rem;
    margin-bottom: var(--spacing-lg);
    flex: 1;
}

.editorial-meta {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 0.85rem;
    color: var(--color-secondary);
}

.read-more {
    color: var(--color-accent);
    font-weight: 600;
}

/* Newsletter Section */
.newsletter-section {
    background: linear-gradient(135deg, var(--color-primary), var(--color-neutral-800));
    color: white;
    padding: var(--spacing-3xl) 0;
}

.newsletter-content {
    text-align: center;
}

.newsletter-content h2 {
    color: white;
}

.newsletter-content p {
