 */
function ProductCard(props) {
    const { id, name, category, price, description, rating, reviews, badge } = props;

    const renderStars = (rating) => {
        const stars = [];
        const filledStars = Math.floor(rating);
        for (let i = 0; i < 5; i++) {
            stars.push(`<span class="star">${i < filledStars ? '★' : '☆'}</span>`);
