/**
 * ProductCard Component
 * Displays a single product with image, info, and action buttons
 */
function ProductCard(props) {
    const { id, name, category, price, description, rating, reviews, badge } = props;

    const renderStars = (rating) => {
        const stars = [];
        const filledStars = Math.floor(rating);
        for (let i = 0; i < 5; i++) {
            stars.push(`<span class="star">${i < filledStars ? '★' : '☆'}</span>`);
        }
        return stars.join('');
    };

    return `
        <article class="product-card">
            <div class="product-image">
                <div style="width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; background: linear-gradient(135deg, #f3f4f6, #e5e7eb); color: #9ca3af; font-size: 3rem;">📦</div>
                ${badge ? `<span class="product-badge">${badge}</span>` : ''}
            </div>
            <div class="product-info">
                <p class="product-category">${category}</p>
                <h3 class="product-name">${name}</h3>
                <p class="product-description">${description}</p>
                <div class="product-rating" aria-label="${rating} out of 5 stars, ${reviews} reviews">
                    <div class="stars">${renderStars(rating)}</div>
                    <span>${rating}</span>
                    <span>(${reviews})</span>
                </div>
                <div class="product-pricing">
                    <span class="product-price">$${price.toFixed(2)}</span>
                </div>
                <div class="product-actions">
                    <button class="product-btn product-btn-add" onclick="handleAddToCart('${id}')">
                        Add to Cart
                    </button>
                    <button class="product-btn product-btn-favorite" aria-label="Add ${name} to favorites">
                        ♡
                    </button>
                </div>
            </div>
        </article>
    `;
}

/**
 * DealCard Component
 * Displays promotional deals with images and time sensitivity
 */
function DealCard(props) {
    const { id, title, description, discount, timeRemaining } = props;

    return `
        <article class="deal-card">
            <div class="deal-image">
                <div style="width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; background: linear-gradient(135deg, #fee2e2, #fecaca); color: #dc2626; font-size: 3rem;">🎁</div>
            </div>
            <div class="deal-content">
                <span class="deal-badge">${discount} OFF</span>
                <h3 class="deal-title">${title}</h3>
                <p class="deal-description">${description}</p>
                <p class="deal-timer">⏱️ ${timeRemaining}</p>
                <button class="btn btn-primary" onclick="handleShopDeal('${id}')">Shop Deal</button>
            </div>
        </article>
    `;
}

/**
 * EditorialCard Component
 * Displays blog/editorial content snippets
 */
function EditorialCard(props) {
    const { id, title, excerpt, tag, readTime } = props;

    return `
        <article class="editorial-card">
            <div class="editorial-image">
                <div style="width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; background: linear-gradient(135deg, #e0e7ff, #f0f4ff); color: #7c3aed; font-size: 2.5rem;">📰</div>
            </div>
            <div class="editorial-content-inner">
                <span class="editorial-tag">${tag}</span>
                <h3 class="editorial-title">${title}</h3>
                <p class="editorial-excerpt">${excerpt}</p>
                <div class="editorial-meta">
                    <span>${readTime}</span>
                    <a href="#" class="read-more">Read more →</a>
                </div>
            </div>
        </article>
    `;
}

/**
